    const index = this.indexes.get(indexName);
    if (!index) {
      throw new Error(`Index ${indexName} not found`);
    }
    if (!ids?.length) {
      return;
    }
    const idSet = new Set(ids);
    index.vectors = index.vectors.filter((vector) => !idSet.has(vector.id));
  }
